#include <stdio.h>
int main(void) {
    FILE *w = fopen("t.txt", "w");
    fprintf(w, "name=%s score=%d\n", "alice", 95);
    fprintf(w, "name=%s score=%d\n", "bob", 88);
    fclose(w);
    FILE *r = fopen("t.txt", "r");
    char name[32]; int score;
    while (fscanf(r, "name=%31s score=%d\n", name, &score) == 2) {
        printf("read: %s %d\n", name, score);
    }
    fclose(r);
    return 0;
}
